import{_ as t,o as n,c as o,a4 as i}from"./chunks/framework.BE47AOxC.js";const h=JSON.parse('{"title":"Offre de soins","description":"Extension Offre de soins : ce que son manifeste déclare.","frontmatter":{"title":"Offre de soins","description":"Extension Offre de soins : ce que son manifeste déclare."},"headers":[],"relativePath":"extensions/offre-de-soins.md","filePath":"extensions/offre-de-soins.md"}'),s={name:"extensions/offre-de-soins.md"};function d(a,e,r,c,l,u){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="offre-de-soins" tabindex="-1">Offre de soins <a class="header-anchor" href="#offre-de-soins" aria-label="Permalink to &quot;Offre de soins&quot;">​</a></h1><p>Sept fiches liées entre elles pour un établissement de santé — bâtiments, unités d&#39;hospitalisation, pôles, services, équipes médicales, médecins, consultations. Seule la fiche du médecin porte des données personnelles, avec son attestation de publication.</p><p><em>Présentation reprise de <a href="/teuthis-cms-distribution/documentation/notice/3-extensions-plugins#annuaires">la notice d&#39;utilisation</a>.</em></p><h2 id="en-bref" tabindex="-1">En bref <a class="header-anchor" href="#en-bref" aria-label="Permalink to &quot;En bref {#en-bref}&quot;">​</a></h2><ul><li><strong>Clé technique</strong> : <code>offre_de_soins</code>, version <code>0.1.0</code>.</li><li><strong>Pack</strong> : <a href="/teuthis-cms-distribution/extensions/packs/secteur-public-fr">Secteur public FR</a>.</li><li><strong>Installée à l&#39;installation par</strong> : aucun profil d&#39;usage. Elle s&#39;ajoute à la main, depuis l&#39;écran Plugins du back-office.</li></ul><h2 id="apports" tabindex="-1">Ce qu&#39;elle apporte <a class="header-anchor" href="#apports" aria-label="Permalink to &quot;Ce qu&#39;elle apporte {#apports}&quot;">​</a></h2><h3 id="types-de-contenu" tabindex="-1">Types de contenu <a class="header-anchor" href="#types-de-contenu" aria-label="Permalink to &quot;Types de contenu {#types-de-contenu}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom</th><th>Clé</th><th>Archétype</th><th>Formulaire public</th></tr></thead><tbody><tr><td>Bâtiment</td><td><code>soins_batiment</code></td><td><code>fiche_annuaire</code></td><td>non</td></tr><tr><td>Unité d&#39;hospitalisation</td><td><code>soins_hospitalisation</code></td><td><code>fiche_annuaire</code></td><td>non</td></tr><tr><td>Pôle</td><td><code>soins_pole</code></td><td><code>fiche_annuaire</code></td><td>non</td></tr><tr><td>Équipe médicale</td><td><code>soins_equipe_medicale</code></td><td><code>fiche_annuaire</code></td><td>non</td></tr><tr><td>Service</td><td><code>soins_service</code></td><td><code>fiche_annuaire</code></td><td>non</td></tr><tr><td>Médecin</td><td><code>soins_medecin</code></td><td><code>fiche_annuaire</code></td><td>non</td></tr><tr><td>Consultation</td><td><code>soins_consultation</code></td><td><code>fiche_annuaire</code></td><td>non</td></tr></tbody></table><h2 id="droits" tabindex="-1">Droits <a class="header-anchor" href="#droits" aria-label="Permalink to &quot;Droits {#droits}&quot;">​</a></h2><p><strong>Droits qu&#39;elle demande à l&#39;organisation</strong> : aucun.</p><h2 id="services-tiers" tabindex="-1">Services tiers et licences <a class="header-anchor" href="#services-tiers" aria-label="Permalink to &quot;Services tiers et licences {#services-tiers}&quot;">​</a></h2><p>Son manifeste ne déclare <strong>aucun service tiers</strong>.</p><h2 id="donnees-personnelles" tabindex="-1">Données personnelles <a class="header-anchor" href="#donnees-personnelles" aria-label="Permalink to &quot;Données personnelles {#donnees-personnelles}&quot;">​</a></h2><p><strong>Oui</strong>, d&#39;après son manifeste :</p><ul><li><strong>Médecin</strong> (<code>soins_medecin</code>) : type de contenu déclaré comme contenant des données personnelles. Champs marqués comme personnels : Prénom (<code>prenom</code>) ; Nom (<code>nom</code>) ; Courriel (<code>courriel</code>) ; Téléphone du secrétariat (<code>telephone_secretariat</code>) ; Ligne directe (<code>ligne_directe</code>) ; Portable (<code>portable</code>) ; Autorisation de publication certifiée (<code>consentement_publication</code>) ; Portrait (<code>image</code>).</li></ul><h2 id="notice" tabindex="-1">Dans la notice <a class="header-anchor" href="#notice" aria-label="Permalink to &quot;Dans la notice {#notice}&quot;">​</a></h2><p><a href="/teuthis-cms-distribution/documentation/notice/3-extensions-plugins#annuaires">La notice d&#39;utilisation présente cette extension</a> (section 3).</p>',17)])])}const f=t(s,[["render",d]]);export{h as __pageData,f as default};
